import 'package:flutter/material.dart';import '../services/moment_service.dart';import '../widgets/moment_card.dart';
class TimelineScreen extends StatelessWidget{final MomentService service;const TimelineScreen({super.key,required this.service});
Future<void> remove(BuildContext context,String id)async{final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Delete moment?'),content:const Text('This moment will be removed from Orbia.'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Delete'))]))??false;if(ok)await service.delete(id);}
@override Widget build(BuildContext context)=>AnimatedBuilder(animation:service,builder:(_,__){final list=service.upcoming;if(list.isEmpty)return const Center(child:Text('No upcoming moments yet.'));return ListView(padding:const EdgeInsets.fromLTRB(18,18,18,120),children:[Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:const Color(0xFF1D2945),borderRadius:BorderRadius.circular(32)),child:Row(children:[const Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('What are you waiting for?',style:TextStyle(color:Colors.white,fontSize:23,fontWeight:FontWeight.w900)),SizedBox(height:7),Text('Your nearest moments, arranged by time.',style:TextStyle(color:Colors.white70))])),Container(width:64,height:64,decoration:BoxDecoration(color:const Color(0xFFF27761),borderRadius:BorderRadius.circular(32)),child:const Icon(Icons.hourglass_top_rounded,color:Colors.white,size:29))])),const SizedBox(height:20),...list.map((m)=>Padding(padding:const EdgeInsets.only(bottom:10),child:MomentCard(moment:m,onFavorite:()=>service.toggleFavorite(m.id),onSave:()=>service.toggleSaved(m.id),onDelete:()=>remove(context,m.id))))]);});}
